def find_all_nonzero_clusters(grid):
    """Find all clusters of non-zero values in grid"""
    if not grid:
        return []
    clusters = []
    visited = [[False for _ in row] for row in grid]
    height, width = len(grid), len(grid[0])

    def bfs(r, c):
        cluster = []
        stack = [(r, c)]
        while stack:
            row, col = stack.pop()
            if not (0 <= row < height and 0 <= col < width):
                continue
            if visited[row][col] or grid[row][col] == 0:
                continue
            visited[row][col] = True
            cluster.append((row, col, grid[row][col]))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                stack.append((row + dr, col + dc))
        return cluster

    for r in range(height):
        for c in range(width):
            if grid[r][c] != 0 and not visited[r][c]:
                cluster = bfs(r, c)
                if cluster:
                    clusters.append([(p[0], p[1]) for p in cluster])  # Just positions

    return clusters

